    """
    Amend the Bugzilla params
    """
    """
    Amend the Bugzilla params
    """
    if not self.all_include_fields():
        if "include_fields" in params:
            fields = params["include_fields"]
            if isinstance(fields, list):
                if "id" not in fields:
                    fields.append("id")
            elif isinstance(fields, str):
                if fields != "id":
                    params["include_fields"] = [fields, "id"]
            else:
