def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

If extract_spec_version is True then will look at the type value to determine
the specification version. In the case that there is no type value or it isn't
valid, then other tests will be based on the version given in self.spec_version.
    """
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory

    # Check basic structure - required fields
    if not isinstance(inventory, dict):
        self.error('E036a')
        return

    # Check for required fields
    if 'id' not in inventory:
        self.error('E036b')
    if 'type' not in inventory:
        self.error('E036c')
    if 'digestAlgorithm' not in inventory:
        self.error('E036d')

    # Validate id field
    if 'id' in inventory:
        if not isinstance(inventory['id'], str):
            self.error('E037a')
        else:
            self.id = inventory['id']
            # Check if it looks like a URI
            if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', self.id):
                self.warning('W005')

    # Validate type field and extract spec version if requested
    if 'type' in inventory:
        type_value = inventory['type']
        if not isinstance(type_value, str):
            if extract_spec_version:
                self.error('E038b')
            else:
                self.error('E038a')
        else:
            # Check if it's a valid OCFL type URI
            type_match = re.match(r'^https://ocfl\.io/(\d+\.\d+)/spec/#inventory$', type_value)
            if type_match:
                if extract_spec_version:
                    extracted_version = type_match.group(1)
                    if extracted_version in self.spec_versions_supported:
                        self.spec_version = extracted_version
                    else:
                        self.error('E038c')
            else:
                if extract_spec_version:
                    self.error('E038c')
                else:
                    self.error('E038a')

    # Validate digestAlgorithm
    if 'digestAlgorithm' in inventory:
        digest_alg = inventory['digestAlgorithm']
        if not isinstance(digest_alg, str):
            self.error('E039')
        else:
            self.digest_algorithm = digest_alg
            # Check if it's a supported digest algorithm
            try:
                digest_regex(digest_alg)
            except ValueError:
                if not self.lax_digests:
                    self.error('E039')
                else:
                    # In lax mode, accept but warn
                    self.warning('W004')

    # Validate contentDirectory
    if 'contentDirectory' in inventory:
        content_dir = inventory['contentDirectory']
        if not isinstance(content_dir, str):
            self.error('E017')
        else:
            self.content_directory = content_dir
            # Check for invalid paths
            if content_dir == '..' or content_dir.startswith('../') or '/../' in content_dir or content_dir.endswith('/..'):
                self.error('E018')
            elif content_dir.startswith('/') or content_dir.endswith('/'):
                self.error('E018')

    # Validate head
    if 'head' in inventory:
        head = inventory['head']
        if not isinstance(head, str):
            self.error('E040')
        else:
            self.head = head

    # Validate versions
    if 'versions' in inventory:
        versions = inventory['versions']
        if not isinstance(versions, dict):
            self.error('E041a')
        else:
            # Get all version keys
            all_versions = list(versions.keys())
            self.all_versions = all_versions

            # Validate version sequence
            self.validate_version_sequence(versions)

            # Validate individual versions
            unnormalized_digests = set()
            self.validate_versions(versions, all_versions, unnormalized_digests)

            # Store unnormalized digests for later use
            self.unnormalized_digests = unnormalized_digests
    else:
        self.error('E041b')

    # Validate manifest
    if 'manifest' in inventory:
        manifest = inventory['manifest']
        if not isinstance(manifest, dict):
            self.error('E042')
        else:
            (manifest_files, digests_used, unnormalized_digests) = self.validate_manifest(manifest)
            self.manifest_files = manifest_files

            # Check that all digests are present and used
            self.check_digests_present_and_used(manifest_files, digests_used)

            # Update unnormalized digests
            if self.unnormalized_digests is not None:
                self.unnormalized_digests.update(unnormalized_digests)
            else:
                self.unnormalized_digests = unnormalized_digests

    # Validate fixity if present
    if 'fixity' in inventory:
        fixity = inventory['fixity']
        if not isinstance(fixity, dict):
            self.error('E043')
        else:
            self.validate_fixity(fixity, self.manifest_files)

    # Check content paths map to versions
    if self.manifest_files is not None and self.all_versions:
        self.check_content_paths_map_to_versions(self.manifest_files, self.all_versions)

