def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

Return values:
    'root' - looks like an OCFL Storage Root
    'object' - looks like an OCFL Object
    'file' - a file, might be an inventory
    other string explains error description

Looks only at "0=*" Namaste files to determine the directory type.
    """
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Check if path exists
    if not fs.path.exists(path):
        parent = fs.path.dirname(path)
        if parent and not fs.path.exists(parent):
            return "Path %s does not exist, nor can parent %s" % (path, parent)
        return "Path %s does not exist" % path

    # If it's a file, return 'file'
    if fs.path.isfile(path):
        return 'file'

    # It's a directory - look for namaste files
    try:
        namastes = find_namastes(path)
    except Exception as e:
        return "Error reading namaste files: %s" % str(e)

    if not namastes:
        return "no 0= declaration file"

    # Check for recognized declarations
    has_root = False
    has_object = False
    unrecognized = []

    for namaste in namastes:
        # namaste is (filename, content) tuple
        if isinstance(namaste, tuple):
            filename, content = namaste[0], namaste[1]
        else:
            filename = namaste
            content = None

        decl = (content or filename or '').strip()

        if re.match(r'^ocfl_\d+\.\d+$', decl):
            has_root = True
        elif re.match(r'^ocfl_object_\d+\.\d+$', decl):
            has_object = True
        else:
            unrecognized.append(decl)

    # Root takes precedence (per test: multiple_declarations → 'root')
    if has_root:
        return 'root'
    if has_object:
        return 'object'
    if unrecognized:
        return "unrecognized declaration file(s): %s" % ", ".join(unrecognized)

    return "no 0= declaration file"

