def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

Also keep a record of any content digests different from those in the root inventory
so that we can also check them when validating the content.

version_dirs is an array of version directory names and is assumed to be in
version sequence (1, 2, 3...).
    """
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}

    # Get root inventory manifest and fixity for comparison
    root_manifest = {}
    root_fixity = {}
    if self.root_inv_validator is not None:
        root_inv = getattr(self.root_inv_validator, 'inventory', {})
        root_manifest = root_inv.get('manifest', {})
        root_fixity = root_inv.get('fixity', {})

    for version_dir in version_dirs:
        inv_path = version_dir + '/inventory.json'

        # Each version SHOULD have an inventory
        if not self.obj_fs.exists(inv_path):
            self.log.error('E064', version=version_dir)
            continue

        # Validate the version inventory
        try:
            inventory, inv_validator = self.validate_inventory(
                inv_path,
                where=version_dir,
                extract_spec_version=False
            )
        except ValidatorAbortException:
            continue

        # Check that head matches the version directory
        if 'head' in inventory and inventory['head'] != version_dir:
            self.log.error('E066', version=version_dir, head=inventory['head'])

        # Record manifest digests not in root inventory
        for digest, paths in inventory.get('manifest', {}).items():
            if digest not in root_manifest:
                prior_manifest_digests.setdefault(version_dir, {})[digest] = paths

        # Record fixity digests not in root inventory
        for algorithm, digests in inventory.get('fixity', {}).items():
            root_algo = root_fixity.get(algorithm, {})
            for digest, paths in digests.items():
                if digest not in root_algo:
                    prior_fixity_digests.setdefault(version_dir, {}).setdefault(algorithm, {})[digest] = paths

        # Validate the inventory digest file if present
        inv_digest_path = inv_path + '.' + self.digest_algorithm
        if self.obj_fs.exists(inv_digest_path):
            self.validate_inventory_digest(inv_path, self.digest_algorithm, where=version_dir)

    return (prior_manifest_digests, prior_fixity_digests)

