    Convert text that defaults to 'w:st="' to 'w-st="'
    """
    """
    Convert text that defaults to 'w:st="' to 'w-st="'
    """
    if content is None:
        return content

    # Handle bytes input
    if isinstance(content, bytes):
        try:
            text = content.decode('utf-8')
        except UnicodeDecodeError:
            text = content.decode('latin-1')
        return text.replace('w:st="', 'w-st="').replace("w:st='", "w-st='").encode('utf-8')

    # Handle string input
    if isinstance(content, str):
        return content.replace('w:st="', 'w-st="').replace("w:st='", "w-st='")

    # For other types (e.g., lxml elements), convert to string first
    try:
        text = etree.tostring(content, encoding='unicode')
        return text.replace('w:st="', 'w-st="').replace("w:st='", "w-st='")
    except Exception:
        return content

