    """
    Return a (sequence, type) pair.
Sequence is derived from *seq*
(or is *seq*, if that is of a sequence type).
    """
    from . import fill_compute_seq
    from . import fill_request_seq
    """
    Return a (sequence, type) pair.
Sequence is derived from *seq*
(or is *seq*, if that is of a sequence type).
    """
    if ct.is_source(seq):
        return (seq, "source")

    if ct.is_fill_compute_seq(seq):
        if not isinstance(seq, fill_compute_seq.FillComputeSeq):
            seq = fill_compute_seq.FillComputeSeq(seq, bufsize=bufsize)
        return (seq, "fill_compute")

    if ct.is_fill_request_seq(seq):
        if not isinstance(seq, fill_request_seq.FillRequestSeq):
            seq = fill_request_seq.FillRequestSeq(seq, bufsize=bufsize)
        return (seq, "fill_request")

    raise exceptions.LenaTypeError(
        "unknown argument type. Must be one of "
        "FillComputeSeq, FillRequestSeq or Source, "
        "{} provided".format(seq)
    )

