def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
For use with subprocess, for argv injection etc. Using fast REGEX.

platform: 'this' = auto from current platform;
          1 = POSIX;
          0 = Windows/CMD
          (other values reserved)
    """
    import re
    import sys
    """
    Multi-platform variant of shlex.split() for command-line splitting.
For use with subprocess, for argv injection etc. Using fast REGEX.

platform: 'this' = auto from current platform;
          1 = POSIX;
          0 = Windows/CMD
          (other values reserved)
    """
    if platform == 'this':
        platform = (sys.platform != 'win32')
    if platform == 1:
        RE_CMD_LEX = r'''"((?:\\["\\]|[^"])*)"|'([^']*)'|(\\.)|(&&?|\|\|?|\d?\>|[&<>()])|("[^"]*")|([^\s&<>()"']+)'''
    elif platform == 0:
        RE_CMD_LEX = r'''"((?:""|\\["\\]|[^"])*)"?()|(\\\\(?=\\*")|\\")|(&&?|\|\|?|\d?>|[<])|("[^"]*")|([^\s&<>()"']+)'''
    else:
        raise AssertionError('unkown platform %r' % platform)

    args = []
    accu = None   # collects pieces of one arg
    for qs, qss, esc, pipe, word, bare in re.findall(RE_CMD_LEX, s):
        if word:
            pass   # most frequent
        elif esc:
            word = esc[1]
        elif pipe:
            pass
        elif qs or qss:
            word = qs or qss
        elif bare:
            word = bare
        else:
            raise AssertionError('unexpected match: %r' % (qs, qss, esc, pipe, word, bare))
        if accu is None:
            accu = word
        else:
            accu += word
        if not (qs or qss or esc):
            args.append(accu)
            accu = None
    if accu is not None:
        args.append(accu)
    return args

