def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.

:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
    """
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the parser option specs for this parser
    parser_specs = self.spec_helper.get_parser_option_specs(parser_name)

    for arg_name, arg_value in values_dict.items():
        if arg_name not in parser_specs:
            continue

        option_spec = parser_specs[arg_name]

        # Skip if no type conversion is needed
        if not option_spec:
            continue

        # Handle different action types
        action = option_spec.get('action', '')

        # For store_true/store_false actions, convert to boolean
        if action in ('store_true', 'store_false'):
            if isinstance(arg_value, str):
                values_dict[arg_name] = arg_value.lower() in ('true', '1', 'yes', 'on')
            continue

        # For append actions, ensure it's a list
        if action == 'append':
            if not isinstance(arg_value, list):
                values_dict[arg_name] = [arg_value]
            continue

        # Handle type conversion based on 'type' field
        arg_type = option_spec.get('type')
        if arg_type is None:
            continue

        # Convert based on type
        try:
            if arg_type == 'int' or arg_type is int:
                if isinstance(arg_value, list):
                    values_dict[arg_name] = [int(v) for v in arg_value]
                else:
                    values_dict[arg_name] = int(arg_value)
            elif arg_type == 'float' or arg_type is float:
                if isinstance(arg_value, list):
                    values_dict[arg_name] = [float(v) for v in arg_value]
                else:
                    values_dict[arg_name] = float(arg_value)
            elif arg_type == 'bool' or arg_type is bool:
                if isinstance(arg_value, str):
                    values_dict[arg_name] = arg_value.lower() in ('true', '1', 'yes', 'on')
            elif arg_type in COMPLEX_TYPES:
                # Complex types are handled separately by resolve_custom_types
                pass
            elif callable(arg_type):
                # Custom type converter
                if isinstance(arg_value, list):
                    values_dict[arg_name] = [arg_type(v) for v in arg_value]
                else:
                    values_dict[arg_name] = arg_type(arg_value)
        except (ValueError, TypeError):
            # If conversion fails, leave the value as is
            # The validation will catch any issues later
            pass

