def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

Try first public message. Then private message. The check if this is a legacy payload.
    """
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try to identify as a public message (MagicEnvelope)
    try:
        body = decode_if_bytes(request.body)
        if body:
            env = MagicEnvelope(payload=body)
            if env.doc is not None:
                return True
    except Exception:
        pass

    # Try to identify as an encrypted message
    try:
        body = decode_if_bytes(request.body)
        if body:
            try:
                data = json.loads(body)
                if isinstance(data, dict) and ("aes_key" in data or "encrypted_magic_envelope" in data):
                    return True
            except (json.JSONDecodeError, ValueError):
                pass
    except Exception:
        pass

    # Try to identify as a legacy payload
    try:
        body = decode_if_bytes(request.body)
        if body and body.strip().startswith("<"):
            try:
                doc = etree.fromstring(encode_if_text(body))
                if doc.tag in ("status_message", "reshare", "retraction", "request", "profile"):
                    return True
            except (etree.XMLSyntaxError, ValueError):
                pass
    except Exception:
        pass

    return False

